async function readRepositoryMemories(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  facets: boolean,
) {
  if (!isEntireApiConfigured(c.env)) return c.json({ error: "Memories are not configured" }, 503)
  const scope = repoScopeFromRequest(c)
  if (scope instanceof Response) return scope
  const pagination = repositoryMemoryReadSchema.safeParse(facets ? {} : c.req.query())
  if (!pagination.success) return c.json({ error: "Invalid memories query" }, 400)
  // The ordinary repo read authorizes access and resolves the primary. Never
  // accept cell/repo IDs from query parameters or route this by home cell.
  const resolved: { routing?: ResolvedRepoRouting } = {}
  const [meta, bearer] = await Promise.all([
    proxyEntireApiRead(c, {
      ...scope,
      userId: c.get("userId"),
      pathFor: (id) => `repos/${id}`,
      search: "",
      requireCanonicalPlacement: true,
      readBodyInWorker: true,
      onResolvedRouting: (routing) => {
        resolved.routing = routing
      },
    }),
    resolveSearchBearerToken(c),
  ])
  if (!meta.ok) return meta
  const viewer = facets ? await resolveMemoryViewer(c, meta) : null
  if (!viewer) void meta.body?.cancel()
  if (!resolved.routing) return c.json({ error: "Repository placement unavailable" }, 503)
  if (!bearer) return c.json({ error: "Not authenticated" }, 401)
  const options = {
    baseUrl: buildBaseUrl(c.env.ENTIRE_API_BASE_URL_TEMPLATE ?? "", resolved.routing.cell),
    repoId: resolved.routing.repoId,
    bearer,

      message: error instanceof Error ? error.message : "Memory read failed",
    }
  }
}
