export async function fetchRepoMemories(
  opts: BrainReadOptions & Partial<z.infer<typeof repositoryMemoryReadSchema>>,
): Promise<
  | { ok: true; data: z.infer<typeof repositoryMemoriesResponseSchema> }
  | Extract<BrainMemoriesResult, { ok: false }>
> {
  return result(async () => {
    // Bound the composed visibility read, not just each individual fetch.
    const deadline = coreFetchSignal(10_000)
    const read = reader({
      ...opts,
      signal: opts.signal ? AbortSignal.any([opts.signal, deadline]) : deadline,
    })
    const params = new URLSearchParams({ pageSize: String(opts.pageSize ?? 50) })
    if (opts.pageToken) params.set("pageToken", opts.pageToken)
    if (opts.q) params.set("q", opts.q)
    for (const key of ["trail", "kind", "status", "author"] as const)
