    const page = await read(
      `repos/${encodeURIComponent(opts.repoId)}/brain/memories`,
      brainMemoriesWireResponseSchema,
      `?${params}`,
    )
    if (page.nextPageToken && page.nextPageToken === opts.pageToken)
      throw new MemoryReadError(502, "Memory pagination did not advance")
