        )
        .map((m) => ({
          ...m,
          trailNumber: trails.get(m.trailId)?.number ?? null,
          trailTitle: trails.get(m.trailId)?.title ?? null,
        })),
    }
  })
}

// The list and facets must use identical visibility and optional label resolution.
function repositoryMemoryVisible(
  trailId: string,
  unanchored: boolean,
  commits: string[],
  onDefault: Set<string>,
) {
  return (
    Boolean(trailId) || unanchored || commits.some((sha) => onDefault.has(membershipSHA(sha) ?? ""))
