      `git/repos/${encodeURIComponent(repoId)}/branch-membership`,
      membershipSchema,
      "",
      { targets: batch },
    )
    for (const sha of batch) {
      if (!membership[sha]) throw new MemoryReadError(502, "Incomplete commit membership response")
      if (membership[sha].onDefaultBranch) onDefault.add(sha)
    }
  }
  return onDefault
}

